def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "u": 3, "^": 4}

    def apply():
        op = operators.pop()
        if op == "u":
            values.append(-values.pop())
            return

        b = values.pop()
        a = values.pop()

        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "^":
            if b < 0:
                raise ValueError
            result = pow(a, b)
        else:
            if b == 0:
                raise ZeroDivisionError
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            result = quotient if op == "/" else a - b * quotient

        values.append(result)

    i = 0
    expect_operand = True

    try:
        while i < len(expr):
            char = expr[i]

            if char == " ":
                i += 1
                continue

            if "0" <= char <= "9":
                number = 0
                while i < len(expr) and "0" <= expr[i] <= "9":
                    number = number * 10 + ord(expr[i]) - ord("0")
                    i += 1
                values.append(number)
                expect_operand = False
                continue

            if char == "(":
                operators.append(char)
                expect_operand = True
            elif char == ")":
                while operators[-1] != "(":
                    apply()
                operators.pop()
                expect_operand = False
            elif char == "-" and expect_operand:
                operators.append("u")
            else:
                while operators and operators[-1] != "(":
                    top = precedence[operators[-1]]
                    current = precedence[char]
                    if top < current or (top == current and char == "^"):
                        break
                    apply()
                operators.append(char)
                expect_operand = True

            i += 1

        while operators:
            apply()

        return values[0]
    except (ZeroDivisionError, ValueError):
        return "error"
